  VALUES 
    (213::BIGINT, 'De lo mejor para llevar Lab de fisica. Ayuda demasiado, los quices a veces son un toque tedioso porque son orales, sin embargo, ayuda demasiado para que lleve las notas altas e incluso ayuda hasta para fisica general. Sabe mucho de los temas. No dude en matricular con él, pasará bastante bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'be75b3af0a1e282dc36c4e41609962d8346013a4e01986976380425b41491cf2'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'El mejor profesor para llevar lab de fisica I sin ninguna duda, califica suave y el curso se vuelve divertido, explica muy bien como hacer los informes y si uno se equivoca en algún informe el da retroalimentación para que en el siguiente saque 100, se pasa facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, '21842a243e152fa6ac7903e421aaef70ecf0db30c22d4aef8d5a4c980831b63c'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es el mejor profe, explica todo muy claro y ayuda un montón con los experimentos y los informes. Super recomendado y ve la IA como una herramienta no como un enemigo. Matricule, no lo dude'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'bbf20dcc17e26e0254b381a9798e4c2b7171359865f1238925ac47b459ca05f5'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (213::BIGINT, 'El mejor profe para llevar lab, ayuda a hacer los informes, nos dice cuales pudieron haber sido los errores y nos dice como podemos explicarlos. Explica bien y es fácil entenderle. Con el experimento si uno no entiende una parte, él viene a la mesa a explicar y ayudarnos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '268ca8ada0761677ac40e480e8091d2471456f317a7e6a18648a1af21bcaed5e'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Súper recomendado. Se hacen bastantes ejercicios en clase y sube prácticas adicionales, si resuelve todo honestamente va súper a los exámenes. Es muy organizado y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'cc0e0324272dea6fbb6d6d132633d27896d34ee12f770c03fcf156f2b9d9663b'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Hace quizes antes de los experimentos, ayuda muchísimo con la elaboración de informes, todo siempre lo deja muy claro con entregas y evaluaciones. Es muy atento a ayudar a los grupos, siempre pasa mesa por mesa. Es definitivamente el mejor profe para llevar este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'c81182afe50f7c3b10810cd7dfc099000caedfafe7c83f75b73f79531f3f599f'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'El profe es bastante bueno, explica lo necesario para que uno pase el curso. No se mete demasiado con teoría y da trucos. Sinceramente la lleva muy suave, solo hace un quiz antes de cada examen, entonces a mi personalmente me gustó pero al mismo tiempo como no había tanto quiz no estudiaba mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2025-07-30T00:00:00+00:00'::TIMESTAMPTZ, '8ed6171b992021e58d68e4567c5b8040ceb5adb3e268ef33bc8fa3464528e1ed'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-22T00:00:00+00:00'::TIMESTAMPTZ, '458e460fc6b6b06e8980f77802ebd38f26673f8bb24261e3ebd1fbb910bb2f43'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'El mejor profe para llevar el lab. Ayuda a la elaboración de los informes previo a la entrega, ayuda a hacer los experimentos, y en la parte de Excel siempre deja videos para que los vaya completando junto a él. Califica súper suave, al final solo debe hacer 1 presentación de informe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '166e2d5f4c1408a3e9ec28c12f35ff28c17d39217feac9a959848939b5bbad5c'::TEXT, ARRAY[607]::BIGINT[]),
