    (213::BIGINT, 'Demasiado buen profe, ayuda a que todo sea fácil y explica bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '30b4215e5bbdbc049f07467784472fa43338694487a1a2f80a3628c6aa896f2f'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'El mejor profe para este curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '4375367ddb3e023b54e2d9bfc4861259de4b6d125aa1a21d59a7b82a6a14cf75'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es lo mejor que hay, le explica a uno como responder el informe, y lo ayuda demasiado a interpretar y completar todo; en serio super buen profe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-11-18T00:00:00+00:00'::TIMESTAMPTZ, '9fd9cfd4fa5cfd86cf73f939a287f3cfbe5a03bd7c8bb21ca46080f70a7b54e9'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'es la mejor opción para llevar lab de física I, explica super bien, le encanta responder preguntas. Y hace que el curso se sienta verdaderamente de 1 crédito'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, '8e677d10699ac0eaa900eca223c2cd48ada47594df1ca0a3c8478cc87fd48d6c'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '601bb99df96bd7af663d4a13aaf137eae69f6b8e1e7616a64d43e7f2c56fb3b2'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Excelente profesor, sus clases son muy amenas y no se sienten largas, explica muy bien y es muy claro, a la hora de calificar puede ser un poco estricto, pero no al punto de ser extremo. Lo recomiendo totalmente para este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'bcf73a66c447756379eaa18be33c8f57b1cd9e2f3f798d76d6f21c92dca26c11'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Muy atento a las dudas de los estudiantes, tiene mucha paciencia a la hora de desarrollar las actividades, ayuda a hacer los informes y califica de forma justa. Matricule con él sin dudarlo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'ac45d38e59080e54adf5b022cffab327273d897892381b5dd60405d5be0053af'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Profesor organizado con lo que hay que ver de la materia, explica bien, las clases son interesantes y divertidas. El laboratorio se pasa con los informes y las experiencias que el explica y enseña como escribir / hacer. Definitivamente un buen profesor, matricule con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'c49feb65f3682c23db15a91bbd6151bd5bdc3497b72cc64065ab6d70966e1b6e'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Si tiene la oportunidad matricule con él, todas las clases son entretenidas, es bastante organizado, súper bueno retroalimentando y siempre está atento a cualquier duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'e887ebefea4d1351a84bf788d7374b0d0d71a1caf944425aadc980a046692475'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Las clases del profe son súper claras, siempre explica bien la parte teórica y el desarrollo de los experimentos también. Si bien califa justo, no es difícil pasar, siempre deja claro los aspectos a evaluar y da ciertos tips que se pueden implementar en los informes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a3638b5d3ab9dcc40ad9ecb62b37a035d6ecc040cae3e51a00b42345e0c7fc10'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es sumamante organizado, desde sus clases hasta los trabajos que a que hacer, califica todo a un tiempo decente, las clases son entretenidas y claras. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'b8bfd90e9ed5c96f54c90f3e1bee2230699a173a9546c759ad51b7a2f3a2411c'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Increíble profesor, deja todo muy claro y ayuda todo lo que se le pida. Las clases son entretenidas y se aprende montones. Matricule sin dudarlo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, '4082b1f32c7756fe19441a7523e5d02ae138da8c8c0d3259a6bb64813dd346be'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Don Ibai Llanos Garatea, un excelente profesor, meta este curso con el , no se va a arrepentir, sus clases son muy entretenidas y el curso se pasa prácticamente solo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-05-20T00:00:00+00:00'::TIMESTAMPTZ, '6b4e21e94d49fe7dcc24ae129a8a25b13dd44ee0879a3fefe90e519994c8765f'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es muy buena persona y explica bastante bien, no califica tan duro y cualquier consulta él con gusto le ayuda.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'f52e42d631cdec10a63d3305635b5d2289c12dbf8d9564d022a5a577962dbead'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Excelente profesor, si puede llevar con él, hágalo, no se va a arrepentir. Explica bastante bien, con buen interés en transmitir la materia lo más claro posible, y siempre dispuesta a ayudar si algo no queda claro. Es una persona amable y simpática.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '64cfd9b64809626cc0604a4d5e72568a26b6ca66455de984f8d94ddd9823534a'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Grande Don Ibai Llanos Garatea'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'da9c2b961f33e49743f47013f885e7ffe60c7a05cc2c730ed0f18dfe73761be4'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Buen profe, las clases van un poco rápidas pero el profe es buena gente y se le entiende bien la clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '59276cbc72d29e1d458a7c693bcbae8795a18360be8a5070613658fe7a4dccb3'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'La clases son cortas y concisas, se toma el tiempo en que todos entiendan, está disponible por si hay dudas o consultas acerca de algún informe y así. Califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '75d1d5368c1a4a32da32feb3ae832c432eff6d8d67aca49ddc0d3264b6ad88b5'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'El curso es fácil, pero si hay asignaciones de cátedra todas las semanas. Da una clase sincrónica a la semana. El profe resuelve 1 o 2 ejemplos durante la clase, se hace una actividad en kahoot y ya. Califica justo y es accesible en consulta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '425ca4cd1cfcdefd9f5471d6a055c7eee072bd6d33e6ed066e545db2aa979626'::TEXT, ARRAY[922]::BIGINT[]),
    (213::BIGINT, 'El profesor hace las clases cortas, da dos clases sincrónicas a la semana. Utiliza Kahoot en las clase, y las clases no duran más de 2 horas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '15e93eead47bff8735c0e6cffe76daae325c09f83af144c020e63a4bc76150a8'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Física III es fácil, pero si hay asignaciones de cátedra todas las semanas. El profe solo da una clase sincrónica, y es entretenida. Resuelve 1 o 2 ejemplos, se hace una actividad en kahoot y ya. Califica justo y es accesible en consulta. El profe es todo buena nota y se parece a Ibai.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6cbc32bf5e2977366b718dc1a576a9ec395ff1f68ef4085334a4aea177a5090a'::TEXT, ARRAY[922]::BIGINT[]),
    (213::BIGINT, 'El profesor es bueno, más creo que le hace falta un poquito de pedagogía, creo que es mucho mejor en la modalidad presencial, pero que es bueno, lo es.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'eca4d2e49c254268a9218b056950ac9fde4f2186c1d582b7c594f18d90a920fe'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es buen profe, virtual los cursos de Física se pasan "fácil" y el profe también ayuda. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, '63f3fea25e51428c2b10b93073f234b35343dd6b924eef08f5170e3f3b067784'::TEXT, ARRAY[922]::BIGINT[]),
    (213::BIGINT, 'Un profesor excelente, siempre dispuesto a ayudar al estudiante y explica sumamente bien, es una excelente opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'eaf84069edfac7cbf1e4efa22a52c4bceb5e2579e46c363d6823b914258baeff'::TEXT, ARRAY[922]::BIGINT[]),
    (213::BIGINT, 'Es buen profe, se le nota la pasión, es un toque aburrido, y a veces hace un arroz con mango explicando.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '60224d642cc1c4009952b03b3d3be5891090807d21591faad1cef3718119c779'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'El curso en sí es manejable, hasta fácil. No hay exámenes, solo muchas asignaciones todas las semanas (dan una de descanso, la 14 creo), pero son cortísimas y accesibles. El profe es tuanis, da ejemplos útiles para los trabajos. Solo tenga buen grupo de trabajo y haga todo y pasa easy.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a836eac7153241495da78dcccfa2c0aabcb557ddf89d45dbf1974c14987b8c4f'::TEXT, ARRAY[922]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'e67e088bf32b32d27f6cd4e84359896f2ab28be58951f4ee18762b2a43ffaf3f'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, '[Virtual] El profe se interesa muchísimo en los estudiantes, es muy buena gente. Sin embargo, resulta confuso cuando explica entonces hay que buscar por aparte. Las asignaciones las puso cátedra, no hubo exámenes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '805c6689cce3bd1b6cf373d154f3d7bc9333aad4916ee6541f8f8efb75a60f05'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es sumamente ordenado y siempre revisa los trabajos rápido. Siempre está dispuesto a ayudar y es muy buena gente, lo recomiendo. Sin embargo con solo el material de clase no es suficiente, hay que estudiar de libros y otras fuentes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '34f0f4ec0f1f3fa1f25bdb1a8327201119d33289fc490ff8774d17682450e28c'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Virtual es bueno, no es obligado conectarse ni tampoco muy necesario pues dan mucho material de apoyo. Explica bien, y ayuda si uno necesita.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'd36d4bb74d7ecece5890d60d31e0da56526fbec5463482eb57de1e0c589fcbff'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es calidad de profesor, las presentaciones que hace son súper útiles, la manera de dar clases es muy práctica, súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '1bd7944088994a91ab7e2b8aab2f38ddde084955b305e4fa1640c65d4588e423'::TEXT, ARRAY[922]::BIGINT[]),
    (213::BIGINT, 'El profe es muy crack y muy accesible, la materia es un poco complicada así que tiene que practicar bastante. Solo da una clase a la semana y en esa resuelve mínimo 2 ejemplos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'f8b147057087c89088a1404b13a9aa539ef7c17aa88ba872dcafa562430a9c98'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Explica bastante bien, es claro con las instrucciones de los trabajos, uno tiene que ser bastante organizado para cumplir con los trabajos, pero en general es muy buen profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '3c043e686a7111600de7e99b1058e379421c67e9956c9217c123d21d3f79de53'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es un profesor muy dedicado y comprensivo. Se nota que le apasiona enseñar. Presencialmente, las clases eran muy interesantes y dinámicas, virtualmente no tanto, pero explica muy bien a pesar de la situación. Demuestre que le importa el curso y él va a ser comprensivo con usted :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'eb751454229a6145c760cb34ba7522f6f4af6b6f723cfe3192566a1058dc8e8d'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Merece una nota bastante mayor a la que tiene. Explica con claridad, se nota que prepara con mucha dedicación sus clases, fue muy comprensivo con la modalidad virtual. Explica claro y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'e63f0be39f6c7a0792d9133eb9c63d05a6ba719d62dac715f37c720cab15e55e'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '7d53aa703f3591459a44125ea9d9f4a0c045ea6db3e5940525e4421187c40f75'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'El profe es súper pura vida, pero como con cualquier profe y cualquier física uno tiene que poner mucho de su parte para entender.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '535c47e81451df265c84f08ba8d8bcf7f7d05b779c27c8b76b03f81bdd4dc312'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'd90251e7bad4a65a7d512041a7fe97eb015e6b479566e00dda6a42f2b4207f44'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Explica todo bastante bien, siempre dispuesto a resolver dudas, califica justo, hace los quices en grupos y le gusta pasar a los estudiantes a la pizarra a resolver cosas (sencillas). En consulta ayuda un montón, pues te explica aún mas detenidamente y te queda ya clarísima la materia. Buen profe.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'ff1227e3772f25fb469116a67b21a1ad42df8aee428ec1c20ed8950b7e1521a7'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Muy buen profe, explica los temas de forma clara, y pone a practicar a los estudiantes en clase, por lo que se aprende a hacer los problemas y se pueden hacer los exámenes sin estudiar más, prácticamente. Trabaja con evaluaciones en el GAAP y sube prácticas por cada tema. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '42a6029c61c3236f51b8a8828c83e25b8e192dc123e77eb19bcc2c8f933ed178'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Excelente profe, explica bastante claro; lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'cf69da109c8418a13bac21efb45e727f81d3c9e05dd011dd01625df3781aad14'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es una mente, y en serio quiere que el estudiante aprenda, experiancias regaladas e informes un queque'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c1219db2378710fb2c2d4ba5e0822864711702e8ff7ead504dea5eaf387955fd'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Se nota que sabe mucho sobre la materia, y ayuda mucho al estudiante si uno se lo solicita'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4a62a06c2eb102acb65b3e530b75c14f49778d60c1710325d91b2bd7cf7020b3'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Excelente, se nota que domina la materia y pide bastante participación en clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '563696d3023bfea92384002ca32ea8ef23f4e65ced2b1705c0b3e775dce2b5d6'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Da puntos extra facilies de consegui, y deja muchos ejercicos que ayudan bastante para el examen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, '1b8f94b46da2b904b54576406acd251b25971bb0ada2934424cefba85b47d243'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Califica suave. Hay que estudiar antes de clase. Da puntos extra que son muy fáciles de ganar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-27T00:00:00+00:00'::TIMESTAMPTZ, '656a22087e8aa6b0be898df420a496b6fed030abb845416796d2de4cb993e3c7'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Lo recomiendo para personas a las que les gusta la participación y mantenerse activo en clase, si prefiere clases magistrales no matricule con él, ya que le gusta que todos participen, hace preguntas y que las personas pasen a la pizarra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, '27d4dc1c7518e80b1a1388469d33a6e5cce62a150738528f09f805f01ec807b7'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es un excelente profesor, claro en las clases, ejemplos de buen nivel, ayuda mucho en consulta. El curso no era interactivo, pero se apoyaba en plickers y discusiones grupales, al menos a mí me gustó trabajar así. No espere que le regale puntos'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-02T00:00:00+00:00'::TIMESTAMPTZ, '7f4c5eaae885f954fc67db0779dbb2cdace418cfb037f77980d9a88b709684a8'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Lo destesté como profe porque pretende que uno sea autodidacta y deja muchísimas tareas, hace que el curso se vuelva más demandante de lo que es. Pero se nota que tiene el conocimiento, solo no sabe administrar las clases.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c31ce4e9989df84076f18360bb01a12019c9ff7003d81d3741972d71ed780ce6'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'No es el mejor profe, pero tampoco es malo. Si lo lleva interactivo nunca falte a las clases y haga todos los trabajos, solo así lo va ayudar al final si lo necesita. Como profesional sabe mucho, las clases resultan interesantes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'e3b2c6e3fa2a411ab62f6872112d672a797193e2fdd7e256d4f1e8be93ae1391'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'El profe explica demasiado bien todo, si usted tiene preguntas, dudas o lo que sea él se las aclara pero lo ve como con cara de estúpido, pero siempre ayuda. Si lo lleva con él tome el curso como si fuera de dos créditos'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'f51d4a0a7599c2fe13a53b212be583a004479e3294f9a0f8982e30a038524c72'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es buen profe, califica algo suave pero tampoco demasiado, no da muchos ejemplos pero si es bastante claro, repite la materia hasta que a todos les quede claro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'f3597b3ff557f2afd773c7f757e70d4d0187eb5f6f6bee7b059865493cf93029'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es un buen profe , califica suave cuando lleve el curso se hizo muy suave , si quiere salir muy bien vaya a tutoria y ya'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-15T00:00:00+00:00'::TIMESTAMPTZ, '7c526a8b79479145b2dfee2f94949b3d8f35ad573dc3e3f7bac0f6e60c31d9d0'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Es un profesor que le va a dar una enseñanza integral. Explica de donde salen las fórmulas y eso hace que los conceptos sean mucho más comprensibles. El ambiente de clase es muy agradable e interactivo. Hay que ser responsable y estudiar por aparte.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5ac509b6072eed7afaf13183a7111e319daf9caa3ec9e3ac8363f21fe7e656b8'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Muy buen profe, explica muy bien la teoria, atiende dudas, resuelve ejercicios dificiles y califica suave, los quices son en grupos y hace bastante practica'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7d2ba5c1c2e0719b11cab00dc237f93536bb6b72df014fd08699002563084e05'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Yo llevé ambos cursos con él, explica bastante bien, se interesa por el aprendizaje de los estudiantes y repite las veces que sea necesario. No califica tan duro y da puntos si ve que usted tiene idea de qué es lo que hay que hacer.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '28e4d5b6654a6ce20edb896fd084156f18618e623619d94886a79065e3b85a50'::TEXT, ARRAY[604, 607, 631]::BIGINT[]),
    (213::BIGINT, 'Es buen profe, un poco odioso en algunas ocasiones pero en consulta aclara muy bien, los quices son sencillos. Califica duro y no regala nada a final de semestre.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '893a0993656db96fa1cbc07465f9e6bbba641eec598bb15dbac3836ff40862b7'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'No es el mejor explicando pero tampoco es malo, nada más de leer el libro antes de la clase porque él no explica muchos conceptos, además no califica suave pero da puntos por intentar los problemas aunque no estén bien, se recomienda matricular con él pero ir de oyente con otro profe si es posible.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '60d62f2f788d07b3d60634b9f02c6061fd157d201c2fd8f8e06a5208a256bb16'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Buen profe en general explica bastante bien, nada más repasar el libro antes de la clase. Tiene que ponerle mucho en la casa porque no da muchos ejemplos.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'b280040304ed9209288ad80b870e3b18b18a5a0ee036cf854b34d3bcd6143a23'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Sabe demasiado pero cree que el estudiante ya conoce de o que se le está hablando entones la mayoría del tiempo va muy rápido y habla de conceptos con los que uno no está familiarizado'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'bb2a738f41ad6f2870908bde119080ce7117e9b696ec91d5e2b4844639dec3cf'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, '336a06e5069959103045f2607cde0b4a04b140169aadbfbf7d489f9a64b19860'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es un excelente profe, amable con los estudiantes y ayuda a quienes se muestran interesados en el curso. Califica duro, pero si usted le pone, aprueba.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7d4ff180a4d83ec5228035542e56b3d6a7f2a39ee6ff5422dba2341229142435'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Buen profe, explica bien, no hace muchos quizes, se nota que le gusta mucho el tema. Ayuda mucho si se va a consulta. Hay que trabajar en clase porque a veces deja la solución de problemas como tarea.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '0c580469f08f5650cfd0ef981cc12633609683b621f9c549112a48f5b8a0c41e'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Un profe muy bueno que explica todo de muy buena forma y además ayuda a aquellos que demuestran interés en la clase. No es tan malo como todo mundo dice'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '36fc9bc8dffffab77d8ebad7691e077c7c0a52d10143db98ad0bcd6666d9e162'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Buen profe, no es malo como muchos dicen.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'da820637e80a2e0e27c73697081954b390e18176574b7e9aff33ed9dce43079c'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Buen profe, explica bien y califica justo. Casi no hace quices. Devuelve evaluaciones super rápido. En consulta es más claro aún y le gusta ver su interés. Hace ejercicios en clase nivel examen. Da libertad de aplicar diferentes métodos a los que el explica.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'aedf85fbcac6c1a8e09100b7252c192e336c11184bdcd3d0d452da35791e7826'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Muy buen Profe, sus clases son claras, siempre y cuando se le ponga atención, son bastante rápidas y por lo general el que no bretea en clase se queda botado, ya que no resuelve todo en la pizarra. Califica bastante bien, muy bueno en consulta y aprecia el interés en la clase.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '47fe42c038dac81798fd75f447647a366a51d69d9337e863f04d8554b617da4b'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Excelente profe, califica algo rudo pero toma en cuenta la participación e interés de los estudiantes, nada mas de poner bastante atención y aprovechar la consulta que ahí el explica aún mejor.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c576f5b297a9503068e7a1c0d9c8a17219bad49744f25070f8d0b5b80c190a1c'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es muy claro dando la materia, pone muchos ejercicios y hace los mas complejos en clases entonces en los examenes son mas facil, no hace quiz solo deja las tareas de catedra y brinda toda la ayuda que usted necesita en consulta, es bueno participar en clase para que note su interes por la materia'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '80de6d60712cc4d58c4a8712d6b285db2f7d256aaa02685c993d07880c76b283'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Al dar la materia, explica poco; al hacer ejemplos los hace muy rápido, a veces no se le entiende y da la impresión de creer que todo es muy lógico o evidente. No obstante, no es realmente mal profesor: califica regular, si uno le pide ayuda la da y en consulta es un bastante bueno explicando.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3874a7374b1b7a0ff8091b4284410466e235af1bde48015742d7cb2160c053a3'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'ayuda mucho y todo se le entiende una vez que se le agarra el toque.. de 43 creo que pasamos mas de 29 por lo que me parece un buen profe, lo prepara para lo mas dificil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0efa84188d22be65ec7f56e406e436acac38ef0e46dea57c2a177e771ae4980c'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c249d674a67112cbf4fc7a65e73c4a0e6e30d093edccfd852f0d9e58f8dc239b'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es un buen profesor, en el area academica explica bien pero si recomiendo estudiar antes de las clases y asistir a tutorias, en general es buen profesor y tiene equilibrio entre lo teorico y lo practico, ademas como persona cada quien tiene su opinion personal aunque si tiene sus aspectos regulares'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '2a43f6bc45f91ad696a5f3c8b55906331db89d6ab1cdc8a21c8be9e47a1ecbd2'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e089384aea59eb977444bbdee3fc2df29a6e916530a1ceb67d041d2580091f09'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Muy arrogante, pero explica bien'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-03T00:00:00+00:00'::TIMESTAMPTZ, '265a9ceb2f5bb5c6b28bee298f89e20062d45ed8d411637a98e6fa93f0a1b883'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Muy arrogante, pero enseña lo necesario para el examen'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-04-05T00:00:00+00:00'::TIMESTAMPTZ, 'a93689f3e5f430abab5c94bf72b4ae69022ead784bb7ece883724364c1a20449'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'explica bien, muy prepotente y no le importa los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'c507082a5b9d58bc68a27903136ca809f67e49421cd918c0343f3d4aae41aa49'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'En mi opinión, sí explica bien. Las clases no son tan aburridas. Sí es duro, pero como cualquier curso de Física. No es de los mejores profes que hay, pero hay peores que él.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '2314c59475bfb1669aadd97723d8d63ce17e10a5911cb8e6f176bc480a8d764a'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Al principio juega mucho de vivo pero si lo llega a tratar y se gana el respeto de el lo trata bien. sabe explicar la materia de manera entendible y se sale con buenos conocimientos de física. Ni se le ocurra caerle mal porque le va feo. Solo deja las tareas de cátedra'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases excelentes']::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, '1ae13609ba3e71114b14a3afdff7cd4d1108a8ae927354ab105783e5c812ed71'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'hay mejores profes, pero diay hay salud.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-10-09T00:00:00+00:00'::TIMESTAMPTZ, '44aed2a6e767c78218241d1d94eed75135d2f5d4ec102de251bf9b85f627ee42'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Explica muy bien la materia pero si califica un poco duro. Si se presentan los informes con todas las especificaciones el curso se pasa muy fácil.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-07-20T00:00:00+00:00'::TIMESTAMPTZ, '48bfe23a02c469894fda9f76b4f83d0cf68bc1b4d74026ed3a06695e1daea83c'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es buen profesor, da la materia necesaria para salir bien en los exámenes. No califica tan duro pero si es arrogante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '4be2822d7db25c36b05404b12df3c690e0dd127cb768c959c7cfe58b29b34228'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Para fisica 2 lo unico que tiene bueno es que no hace quices, el explica como si uno supiera, para el segundo y tercer examen lo abandona a uno, ni hace ejemplos en la clase, solo se preocupa por demostrar las formulas'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '06193b49305dfeee9c3b4fe5a62c408792c92112fb025a8412fc5c6ca7804504'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '63a688aa286222aafed0064047b7ea5d925980869be64b11496731944d7275d3'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'el profe es buena persona y hace que uno se interese en aprender. pero explica y le habla a los estudiantes como si fueran físicos como el. según mi experiencia califica según la persona.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cab812abab35767a5f0446219fa43d92313b8b9fef33dd322e3d38e7eed78d2c'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Cuesta entenderle la teoría, no es muy claro. Muy accesible para brindar ayuda o atender dudas. Nunca realiza quices por lo que hay que practicar mucho, sólo realiza las tareas de cátedra'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7afdee6264fa72b7f52870278f357629d9ffaea92362e34144c1a5ffe3ffce18'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Buen profe. Su forma de ser es algo estresante, pero uno se acostumbra. Sabe mucho, puede aclarar cualquier duda. Empieza evaluando justo y se vuelve suave al final con los que vayan a clase. No se detiene en teoría, espera que uno lea antes. Se aprende. Primera vez, póngale. Repitente, un queque'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, '704c6e7cec66e2bdf8ccb95641d85713c400667c901cade1cc39d708c65b8033'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Buen profe, se enreda un poco pero en general si se le entiende bastante, en consulta ayuda bastante, califica justo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '6509c584cf6e852c2781516244aa46077611e7021b7d183e9847720d6a187f81'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Explica regular, hace pocos ejercicios y califica duro.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-19T00:00:00+00:00'::TIMESTAMPTZ, '1916518ddaf31dfd4c6ca948f9dd481fa61974ae1dfcd02fa1678154b610e5f6'::TEXT, ARRAY[631]::BIGINT[]),
    (213::BIGINT, 'Es exelente profe , no deja quices pero si muchas tareas, a veces no se le entiende pero en consulta es un amor. Es intimidante pero tambien es super atento y extremadamente responsable.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'f7aa9c36c2bcfe655bf18060f14642fbc3aef23d4a259d0ba15fa46961a5743d'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-13T00:00:00+00:00'::TIMESTAMPTZ, '6d3a06f193a6dc64a9dfa13d9767ff90da3b9155aa6bf68a35c47e8aec7128ee'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Bueno explicando, a veces se enreda pero se le entiende. Califica justo y es bueno atendiendo dudas'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '71fc70d786e5148bbc07eeaae5833535ec18b41420a79d31f55ef2b82ef12f26'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'No se hacen quices pero sí deja tareas muy largas, sin embargo siempre trata que todos entiendan'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'daff65ce6e3e4e17705b8d98edef9251e4631fb12e820fc9e989699e85a45f06'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Para lab de fisica es excelente explica super bien y califica justo. Atiende consultas y es muy buena persona. Si no trabajas y no haces nada te lo hechas encima, le gusta formar estudiantes responsables. Recomendado!!!!'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f1affe29851ae57e296de61bd76cf979f03c1541188b7bed8544e69b57efbf78'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'En el curso de teoría es muy bueno. Las tareas que deja ayudan bastante, explica toda la teoría y resuelve ejercicios difíciles'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5e7378cfcd73559cd6975e6d791655aab68d81f454b1994e41de858ba5ac7a1c'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'No hace quices pero en cambio hay que hacer tareas, explica todo pero espera que uno llegue con el capitulo del libro previamente leido. Explica como se llega a cada fórmula pero a veces uno se enreda más. Generalmente uno sale temprano de clases.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'bd563e9487dba54c2371b8bc0885a7e5adfbd63156410633f1ff0da3d46f34fa'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'No lo recomiendo, es muy duro para calificar, y para ser un curso de 1 crédito, se le dedica más tiempo que a uno de 4, en serio. Va a aprovechar cualquier oportunidad para hacerlo quedar como un idiota. Lo único es que contesta los correos rápido jaja, pero 0 recomendado.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'f4831528254f4fe7b29080c667da0efc88bf879acae93a85779f7a04aa6b84de'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '4c099e786b6f6d20e677b438926c102686472379ccb61209e811d9b80c549255'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Tiene el ego por los cielos, la verdad no es una clase en la que se quiera estar principalmente por el. A mi parecer ningun estudiante le entiende y los examenes son duros, hasta 0 nos hemos sacado.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2015-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'ee890ecd2bbf2cf9c376c79d535c0b2531a66c660d700c0491c9087ea4fe7fdf'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Al inicio exige mucho, pero al final ayuda a todos a pasar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9a77cf95a15e4f5a28df66ee4176027ecc68d32a6ecc1ba5526acade8279e5d2'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (213::BIGINT, 'Al principio parecerá estricto, pero uno se da cuenta de que si hace los trabajos bien (no necesariamente excelente), él los califica con más de 80. No es razón para no ponerle; el curso tiene su complejidad.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '996e8e338f15e2ec7d02d76277d1ad83a42fff4c6ca3539ddda4d1f4d25f80d1'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Un profesor muy juega vivo, se creer la persona mas inteligente y cuando pregunta o va a consulta lo hace sentir que ud no vale nada, mas bien se desmotiva mas'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '6b0cf3d79d04e29d6a603b68919ef7df22cba0f9c418dfbc8047e216aefd630f'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'El se cree doña toda, y cada uno de los comentarios q hace le pone ese tono sarcástico como diciendo ud para q esta aqui. me dio clases solo una semana y asi se ganó mi aborrecimiento'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'aa023a86d5df48f804e8afe95de5572a7aa6dac5d0a25890385acd70e229fe4b'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Es un profesor serio y estricto, si entiendes y estudias todo saldrá bien, pero si pretendes que el curso sea regalado y Fácil, todo lo contrario hay que esforzarse y estudiar, se aprende mucho con el, responde los correos de inmediato, evalúa fuerte pero congruente a lo que enseña.Un muy buen profe'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '96be9c3f21a2a37fa79046a51056c6a4674267233c7c91f3f3ee78927a916a44'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es buen profe, enseña física bien y no regala el curso, que es como debe ser para un curso así'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'caa710f3fd51b2da81f91ff2a0f9701e36a978becfe9a409448dbfeb6330e79b'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, '8d90be7ce46477c984d6f6d29f338d2712f8a3aa2192197677f248b6062c6707'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '12ad16dbb252c6e8fbd718af509548910e8d71eaf2ad9bdc9ca94ae3b2276ca6'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Guácala su comportamiento, no he conocido un profesor más engreído y arrogante. Explica bien pero basa su clase en hacerle saber que para él todos ls estudiantes son unos idiotas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'd6c8262eb1d30377cbfc4ecf47643f1a612b59100792c0b9dfb8ad9ce56d926b'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Explica muy claro, y tal vez al inicio parece muy odioso, pero al final resulta ser muy amable. Pregunten todo lo que puedan aunque el profe no le haga buena cara, él siempre va a contestarle la pregunta y se aprende mucho. Sáquenle provecho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-11T00:00:00+00:00'::TIMESTAMPTZ, '611da7c10395c2d9e801201053b8efca34560bb3311d4ed3aaf61d459c1c2f40'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'engreído, y aplica el menor esfuerzo para el y la mayor dificultad para el estudiante. aunque sea requisito matemática se paga por un curso claro y acorde a lo requerimientos que pide el tec, es necesario que haga recordatorios de la parte matemática para poderse guiar mejor a la hora de los exam'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-23T00:00:00+00:00'::TIMESTAMPTZ, '8eab3a8f4965f2f8044792af66d3e7ed6b2674995654ffcf3ce7a5d9fa8cc13a'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'Muy engreido y hace el curso un poco más difícil de lo que debería ser.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, '152dd471869b8236f0abd3a601f2e8d63d425649af1e971ccae350893b5354cf'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Es muy engreido, lo hace sentir idiota a uno, y da por un hecho que un sabe todo, en resumen, no lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '61c1785c441b109e448cf76c2a73ca749c9e71a11c1498a283e467234af23aba'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (213::BIGINT, 'Es bastante estricto pero explica bien, siempre atiende las dudas y uno entiende aunque a veces es un poco crecido, asume que todo es facilísimo...califica duro informes...exámenes y quices no. Hace que las de física I no sea tan regalado.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'e36fd0b996195266edf51c30dc51bb31353a7dc342dc60ea20132040874d8581'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (213::BIGINT, 'buen profe, contesta los correos y consultas casi que de inmediato. se aprende a hacer informes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '575e43fde66fa3a632e5fdf52461b5609e45fdf94f242cf5e6ba158922415dde'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (213::BIGINT, 'Muy agrandado y supone que todo problema es fácil !!'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b3cbb46c7a6b30898d856be4aaa48a8f9106ab9a08dcbfcf0bd69c5e085b3002'::TEXT, ARRAY[604]::BIGINT[]),
    (213::BIGINT, 'No es comprensivo, hace de un curso fácil un toque más duro. Pasé con una buena nota gracias a que me esforcé bastante, pero algunos no pasan con él. También suele ser muy ponposo y grosero a la hora de contestar dudas y al calificar reportes'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '47f07adc2632ca0af13c7b5871e9e2e28ee45de1025fce561e4ac4a3ace63668'::TEXT, ARRAY[607]::BIGINT[]),
    (213::BIGINT, 'Excelente!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '34b649a7b116fcc980f9167820e1a4c0ff8018b1f4b5536097610362c69bb36e'::TEXT, ARRAY[607]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
